phy'=>'Tipografi','Colours & background'=>'Warna & latar belakang','Border'=>'Batas','Effects'=>'Efek','Motion'=>'Gerakan','Advanced'=>'Lanjutan','up to %d px'=>'hingga %d px','from %d px'=>'dari %d px','all widths'=>'semua lebar','Screen size'=>'Ukuran layar','Hover'=>'Sorot','Reset every value set for %s'=>'Reset setiap nilai yang ditetapkan untuk %s','Inherited from %s'=>'Diwarisi dari %s','Reset %s'=>'Setel Ulang %s','Hide on'=>'Sembunyikan pada','%1$s (%2$d set)'=>'%1$s (%2$d set)','Replace icon'=>'Ganti ikon','No icons match.'=>'Tidak ada ikon yang cocok.','Regular'=>'Reguler','Brands'=>'Merek','Sharp'=>'Tajam','Bold'=>'Tebal','Fill'=>'Isi','Duotone'=>'Duotone','This icon set could not be loaded. Check your connection and try again.'=>'Kumpulan ikon ini tidak dapat dimuat. Periksa koneksi Anda dan coba lagi.','Search icons'=>'Cari ikon','Search all sets'=>'Cari semua kumpulan','%d icons'=>'%d ikon','Loading icon sets…'=>'Memuat kumpulan ikon…','%s icons'=>'ikon %s','All sets'=>'Semua set','This file is not a valid SVG image.'=>'Berkas ini bukan gambar SVG yang valid.','The icon could not be uploaded.'=>'Ikon tidak dapat diunggah.','Upload SVG'=>'Unggah SVG','Delete selected upload'=>'Hapus unggahan yang dipilih','Scripts, links and external references are removed from uploaded SVG files before they are saved.'=>'Skrip, tautan, dan referensi eksternal akan dihapus dari file SVG yang diunggah sebelum disimpan.','My uploads'=>'Unggahan saya','Align items'=>'Ratakan item','Stretch'=>'Rentangkan','Baseline'=>'Garis dasar','Align self'=>'Ratakan sendiri','Auto'=>'Otomatis','Aspect ratio'=>'Rasio aspek','Background colour'=>'Warna latar belakang','Box shadow'=>'Bayangan kotak','Column span'=>'Rentang kolom','Text colour'=>'Warna teks','Cursor'=>'Kursor','Pointer'=>'Penunjuk','Move'=>'Pindahkan','Grab'=>'Ambil','Not allowed'=>'Tidak diizinkan','Crosshair'=>'Crosshair','Zoom in'=>'Perbesar','Block'=>'Blokir','Inline'=>'Sebaris','Inline block'=>'Blok inline','Inline flexbox'=>'Flexbox sebaris','Inline grid'=>'Kisi sebaris','Contents only'=>'Hanya isi','Hidden'=>'Tersembunyi','Basis'=>'Dasar','Row reversed'=>'Baris dibalik','Column'=>'Kolom','Column reversed'=>'Kolom dibalik','Grow'=>'Kembangkan','Shrink'=>'Kecilkan','Wrap'=>'Perkecil','No wrap'=>'Tanpa bungkus','Wrap reversed'=>'Balik urutan baris','Font'=>'Font','Italic'=>'Miring','Weight'=>'Bobot','Thin (100)'=>'Tipis (100)','Extra light (200)'=>'Ekstra ringan (200)','Light (300)'=>'Ringan (300)','Regular (400)'=>'Reguler (400)','Medium (500)'=>'Sedang (500)','Semi bold (600)'=>'Semi tebal (600)','Bold (700)'=>'Tebal (700)','Extra bold (800)'=>'Ekstra tebal (800)','Black (900)'=>'Hitam (900)','Gap'=>'Jarak','Area name'=>'Nama area','Named areas'=>'Area bernama','Offsets'=>'Offset','Justify content'=>'Ratakan konten','Space between'=>'Jarak antar','Space around'=>'Ruang kosong di sekitar','Space evenly'=>'Ratakan jarak','Letter spacing'=>'Spasi huruf','Line height'=>'Tinggi baris','Margin'=>'Margin','Max height'=>'Tinggi maks','Max width'=>'Lebar maks','Min height'=>'Tinggi minimum','Min width'=>'Lebar min','Overflow'=>'Meluap','Visible'=>'Terlihat','Clip'=>'Salin','Scroll when needed'=>'Gulir jika diperlukan','Always scroll'=>'Selalu gulir','Padding'=>'Padding','Place items'=>'Tempatkan item','Relative'=>'Relatif','Absolute'=>'Absolut','Fixed'=>'Tetap','Corner radius'=>'Radius sudut','Row span'=>'Rentang baris','Justify'=>'Ratakan Kanan-Kiri','Decoration'=>'Dekorasi','Overline'=>'Garis atas','Strikethrough'=>'Coret','Text shadow'=>'Bayangan teks','Letter case'=>'Huruf besar-kecil','Uppercase'=>'Huruf besar','Lowercase'=>'Huruf kecil','Capitalise'=>'Kapitalisasi','Transition'=>'Transisi','Stack order (z-index)'=>'Urutan tumpukan (z-index)','Add screen sizes of your own, such as a large desktop, a landscape tablet or a small phone.'=>'Tambahkan ukuran layar Anda sendiri, seperti desktop besar, tablet lanskap, atau ponsel kecil.','Applies'=>'Berlaku','up to a width'=>'hingga lebar'